  `flock -w 10 /tmp/lock ${NI}`,
  `chroot --userspec root /jail ${NI}`,
  `sudo -u ls ${NI} evil`,
  `flock ls ${NI} evil`,
  `timeout --foreground -k ls 5 ${NI} evil`,
  `xargs -a ls ${NI} evil`,
  `git -C ls exec ${NI} evil`,
  `env -u type ${NI} evil`,
  `${NI} left-pad`,
  "nix shell nixpkgs#cowsay",
  `echo hi; ${NI} evil`,
];

